-- Revisión del banco de preguntas (3 de noviembre de 2026). Cambia datos, no el esquema.
--   · Ajuste de niveles de 28 preguntas cuyo contenido no correspondía a su nivel.
--   · Correcciones: 234 revelaba la respuesta de 233; 137, 138 y 139 rotulaban mal 2P/3P;
--     14 (PDVSA se creó en 1975; la nacionalización entró en vigor en 1976).
--   · Opciones absurdas reemplazadas por distractores creíbles (179, 223, 231, 233, 237, 238, 241).
--   · Desactivadas: 128 y 166 (preguntan el propósito de la clase) y 187, 188, 189, 190, 199
--     (repetían la misma tabla de CAPEX/OPEX; se conservan 197, 200, 229 y 231).
--   · 50 preguntas nuevas de nivel 5, 10 por tema.
-- Cada cambio verifica el valor anterior, para no tocar una pregunta equivocada.

begin;

-- ── Niveles ──
update parcial.preguntas set dificultad = 3 where dificultad = 5 and id in (38, 119, 223, 232, 240);
update parcial.preguntas set dificultad = 4 where dificultad = 5 and id in (118, 120, 158, 229, 237, 238);
update parcial.preguntas set dificultad = 3 where dificultad = 4 and id in (33, 109, 110, 112, 116, 152, 191, 192);
update parcial.preguntas set dificultad = 2 where dificultad = 4 and id = 36;
update parcial.preguntas set dificultad = 2 where dificultad = 3 and id = 23;
update parcial.preguntas set dificultad = 2 where dificultad = 1 and id in (123, 127);
update parcial.preguntas set dificultad = 3 where dificultad = 2 and id = 133;

-- ── Desactivadas ──
update parcial.preguntas set activa = false where id in (128, 166, 187, 188, 189, 190, 199);

-- ── Correcciones de contenido ──
update parcial.preguntas
   set enunciado = 'Un prospecto tiene estas probabilidades: roca madre 0,9, migración 0,8, roca yacimiento 0,7, trampa 0,6 y sello 0,5. Un estudio sísmico eleva la probabilidad de la trampa a 0,9. ¿Cuál es el nuevo Pg?'
 where id = 234 and correcta = 1 and enunciado like 'En el prospecto anterior%';

update parcial.preguntas
   set enunciado = '¿Qué escenario de reservas usan los ejecutivos como base para presupuestos, flujo de caja y fusiones y adquisiciones?',
       opciones = '["El escenario 2P (probadas + probables, P50)", "El escenario 1P (probadas, P90)", "El POES total del yacimiento", "El escenario 3P (probadas + probables + posibles, P10)"]'
 where id = 137 and correcta = 0;

update parcial.preguntas
   set enunciado = '¿Qué representa el escenario 3P (probadas + probables + posibles, o P10)?'
 where id = 138 and correcta = 3;

update parcial.preguntas
   set opciones = '["El escenario 3P (probadas + probables + posibles)", "Las reservas probadas (1P)", "Todo el POES del yacimiento", "El escenario 2P (probadas + probables)"]'
 where id = 139 and correcta = 1;

update parcial.preguntas
   set enunciado = '¿En qué año entró en vigor la nacionalización de la industria petrolera venezolana, con PDVSA como casa matriz?'
 where id = 14 and correcta = 1;

-- ── Distractores creíbles en lugar de opciones absurdas (la correcta no cambia de posición) ──
update parcial.preguntas set opciones = '["A la máxima tasa durante el primer año", "Lo más rápido posible", "A velocidad moderada", "Produciendo primero el gas de la capa y después el petróleo"]'
 where id = 179 and correcta = 2;
update parcial.preguntas set opciones = '["Una baja del precio, porque sobra crudo en los tanques", "Ningún efecto, porque las reservas mundiales no cambian", "Un alza del precio, por el temor a una escasez de suministro", "Precios estables, porque la OPEP compensa de inmediato todo el volumen perdido"]'
 where id = 223 and correcta = 2;
update parcial.preguntas set opciones = '["El de gas en solución, porque su CAPEX inicial es bajo", "Ambos igual, porque tienen las mismas reservas", "El de empuje hidráulico, porque su menor riesgo da más certeza sobre la producción", "El de gas en solución, porque produce más rápido al inicio y paga antes la deuda"]'
 where id = 231 and correcta = 2;
update parcial.preguntas set opciones = '["Aproximadamente 0,15", "Aproximadamente 0,50", "Aproximadamente 0,70", "Aproximadamente 0,30"]'
 where id = 233 and correcta = 0;
update parcial.preguntas set opciones = '["Porque un éxito puede abrir un play nuevo con volúmenes grandes que compensan el riesgo", "Porque en las cuencas fronterizas perforar siempre cuesta menos", "Porque una cuenca sin pozos previos tiene menos riesgo geológico", "Porque sus volúmenes pueden registrarse como reservas probadas antes de perforar"]'
 where id = 237 and correcta = 0;
update parcial.preguntas set opciones = '["Una revisión que aumentó la porosidad estimada del yacimiento", "Una caída del precio que volvió no comercial parte del volumen", "Un aumento del factor de recobro del campo", "El descubrimiento de un yacimiento nuevo"]'
 where id = 238 and correcta = 1;
update parcial.preguntas set opciones = '["Que la trampa esté vacía, porque el petróleo migró antes de que la trampa existiera", "Que la trampa esté llena, porque el petróleo espera a que se forme", "Que la trampa contenga petróleo más liviano, porque migró una distancia mayor", "Que la trampa esté llena de gas, porque el petróleo se transformó mientras esperaba"]'
 where id = 241 and correcta = 0;

-- ── 50 preguntas nuevas de nivel 5 ──
insert into parcial.preguntas (tema, enunciado, opciones, correcta, dificultad)
select x->>'t', x->>'e', x->'o', (x->>'c')::int, 5
  from jsonb_array_elements($j$[
{"t":"Introducción al petróleo y gas","c":0,"e":"Un crudo de 8° API y otro de 30° API se vierten en agua dulce. ¿Qué ocurre?","o":["El de 8° API se hunde y el de 30° API flota, porque 10° API equivale a la densidad del agua","Ambos flotan, porque todo el petróleo es menos denso que el agua","Ambos se hunden, porque el petróleo es más denso que el agua","El de 30° API se hunde y el de 8° API flota, porque a mayor grado API mayor densidad"]},
{"t":"Introducción al petróleo y gas","c":1,"e":"Un país tiene una relación R/P de 40 años. Si duplica su producción sin agregar reservas nuevas, ¿cuál será su nueva R/P?","o":["Unos 80 años","Unos 20 años","Sigue en 40 años, porque las reservas no cambiaron","Unos 10 años"]},
{"t":"Introducción al petróleo y gas","c":2,"e":"Dos crudos de igual calidad se venden al mismo precio en el puerto. Uno sale de un campo a 50 km del terminal y otro de un campo a 900 km sin oleoducto. ¿Cuál deja mayor ingreso neto al productor?","o":["El lejano, porque recorre más distancia y se cotiza mejor","Ambos igual, porque el precio en el puerto es el mismo","El cercano, porque su costo de transporte hasta el puerto es menor","El lejano, porque el transporte por carretera es más barato que por oleoducto"]},
{"t":"Introducción al petróleo y gas","c":3,"e":"Si el precio del crudo sube con fuerza y el de la gasolina se mantiene, ¿qué ocurre en una empresa integrada?","o":["Ganan por igual el upstream y la refinación","Pierde el upstream y gana la refinación, que vende más gasolina","No cambia nada, porque las ganancias de un segmento siempre anulan las del otro","Gana el upstream, que vende el crudo más caro, y se reduce el margen de refinación, que lo compra más caro"]},
{"t":"Introducción al petróleo y gas","c":0,"e":"Para exportar crudo extrapesado de 8° API se le mezcla nafta liviana. ¿Qué efecto tiene la mezcla?","o":["Sube la gravedad API y baja la viscosidad, lo que facilita bombearlo y venderlo","Baja la gravedad API y lo vuelve todavía más pesado","Elimina todo el azufre del crudo","Convierte el crudo en gas natural para transportarlo por gasoducto"]},
{"t":"Introducción al petróleo y gas","c":1,"e":"Si se cerrara el estrecho de Ormuz, ¿por qué los importadores de Asia serían los más afectados?","o":["Porque Asia no tiene ningún puerto petrolero propio","Porque la mayor parte del crudo que sale del golfo Pérsico por Ormuz va hacia Asia","Porque Asia produce más petróleo que el golfo Pérsico","Porque todo el petróleo de Asia se transporta por el canal de Suez"]},
{"t":"Introducción al petróleo y gas","c":2,"e":"Una refinería sencilla, sin unidades de conversión ni de desulfuración, debe elegir entre un crudo liviano dulce y uno pesado agrio. ¿Cuál le conviene?","o":["El pesado agrio, porque siempre rinde más gasolina","Cualquiera, porque toda refinería procesa cualquier crudo de la misma forma","El liviano dulce, porque rinde más productos valiosos sin procesos de conversión ni de remoción de azufre","El pesado agrio, porque el azufre mejora la calidad de la gasolina"]},
{"t":"Introducción al petróleo y gas","c":3,"e":"Si la OPEP+ recorta su producción conjunta y la demanda mundial no cambia, ¿qué es lo más probable?","o":["El precio baja y los productores fuera del grupo pierden mercado","El precio no cambia, porque la producción total no afecta el precio","Los productores fuera del grupo deben recortar en la misma proporción","El precio tiende a subir y los productores fuera del grupo venden más caro y pueden ganar cuota"]},
{"t":"Introducción al petróleo y gas","c":0,"e":"Con un gradiente geotérmico de 30 °C por km y 20 °C en superficie, ¿a qué profundidad aproximada una roca madre alcanza unos 110 °C, dentro de la ventana del petróleo?","o":["Unos 3 km","Unos 1 km","Unos 5,5 km","Unos 11 km"]},
{"t":"Introducción al petróleo y gas","c":1,"e":"Un país exporta 1 millón de barriles diarios y el precio sube de 60 a 75 US$ por barril. ¿Cuánto aumentan aproximadamente sus ingresos anuales por exportación?","o":["Unos 15 MM$","Unos 5.500 MM$","Unos 450 MM$","Unos 27.000 MM$"]},
{"t":"Tectónica de placas","c":2,"e":"En un borde de placas los sismos son cada vez más profundos a medida que se avanza tierra adentro desde la fosa. ¿Qué indica?","o":["Un borde divergente con una dorsal activa","Un borde transformante con desplazamiento lateral","Un borde convergente donde una placa oceánica se hunde bajo la continental","Un punto caliente en el centro de la placa"]},
{"t":"Tectónica de placas","c":3,"e":"El Atlántico Sur mide unos 3.000 km de ancho y comenzó a abrirse hace unos 130 millones de años. ¿A qué velocidad media se separaron Suramérica y África?","o":["Unos 0,23 cm por año","Unos 23 cm por año","Unos 230 cm por año","Unos 2,3 cm por año"]},
{"t":"Tectónica de placas","c":0,"e":"Un rift continental que se detuvo antes de formar un océano (rift abortado) es un buen objetivo petrolero porque suele tener:","o":["Lagos profundos con roca madre lacustre y bloques limitados por fallas normales que forman trampas","Corteza oceánica nueva sin sedimentos","Volcanes activos que destruyen la materia orgánica","Rocas metamórficas sin porosidad, como un escudo"]},
{"t":"Tectónica de placas","c":1,"e":"Si el Mar Rojo sigue abriéndose durante decenas de millones de años, ¿en qué se convertirán sus bordes con África y Arabia?","o":["En zonas de subducción con volcanes","En márgenes pasivos con cuencas de sedimentos gruesos, como las costas del Atlántico","En una cordillera de colisión, como el Himalaya","En escudos antiguos y estables, sin sedimentos"]},
{"t":"Tectónica de placas","c":2,"e":"¿Por qué los Andes tienen muchos volcanes activos y el Himalaya casi ninguno?","o":["Porque el Himalaya es más antiguo y sus volcanes ya se erosionaron","Porque los Andes están sobre un punto caliente, como Hawái","Porque en los Andes una placa oceánica se hunde y genera magma, mientras que el Himalaya es un choque de dos continentes sin subducción oceánica activa","Porque el Himalaya está en un borde divergente"]},
{"t":"Tectónica de placas","c":3,"e":"En una falla de rumbo, un tramo curvo hace que los bloques se compriman al deslizarse. ¿Qué estructura se forma allí?","o":["Un valle de rift con fallas normales","Una dorsal oceánica","Una fosa de subducción","Pliegues y fallas inversas que levantan el terreno y pueden formar trampas"]},
{"t":"Tectónica de placas","c":0,"e":"¿Por qué las cuencas de antepaís, como la Cuenca Oriental de Venezuela, suelen ser muy productivas?","o":["Porque acumulan sedimentos gruesos que entierran la roca madre hasta la ventana de generación, y el frente de la cordillera forma pliegues que sirven de trampas","Porque están sobre dorsales oceánicas que calientan la roca madre","Porque no tienen sedimentos y el petróleo aflora directamente","Porque están en escudos antiguos y estables, sin fallas"]},
{"t":"Tectónica de placas","c":1,"e":"Una banda magnética a 60 km de la dorsal tiene 3 millones de años. Si la expansión fue constante, ¿qué edad tendrá el fondo oceánico a 120 km de la dorsal?","o":["Unos 1,5 millones de años","Unos 6 millones de años","Unos 3 millones de años","Unos 12 millones de años"]},
{"t":"Tectónica de placas","c":2,"e":"¿Por qué los márgenes activos, con subducción, suelen tener menos petróleo que los márgenes pasivos?","o":["Porque en ellos nunca se deposita materia orgánica","Porque el agua del océano disuelve el petróleo","Porque la deformación, los sismos y el magmatismo rompen sellos y trampas, y el espacio para acumular sedimentos es más limitado","Porque la subducción convierte el petróleo en roca"]},
{"t":"Tectónica de placas","c":3,"e":"En ambas orillas del Atlántico Sur hay capas de sal de la misma edad, depositadas cuando el océano empezaba a abrirse. ¿Qué implica esto para la exploración?","o":["Que solo una de las dos orillas puede tener petróleo","Que la sal impide cualquier acumulación de petróleo","Que las dos orillas tienen edades geológicas distintas","Que un gran hallazgo bajo la sal en una orilla aumenta la probabilidad de un sistema similar en la orilla opuesta"]},
{"t":"Sistemas petroleros","c":0,"e":"En el método volumétrico, una roca tiene 25 % de porosidad y 40 % de saturación de agua. ¿Qué fracción del volumen total de roca ocupan los hidrocarburos?","o":["15 %","10 %","25 %","60 %"]},
{"t":"Sistemas petroleros","c":1,"e":"Un anticlinal tiene un cierre de 100 m, pero su sello solo soporta una columna de 40 m de petróleo antes de dejarlo escapar. ¿Qué altura de columna de petróleo cabe esperar?","o":["Unos 100 m, porque el cierre define la columna","Unos 40 m, porque la capacidad del sello limita la columna aunque el cierre sea mayor","Unos 140 m, porque se suman el cierre y el sello","Ninguna, porque un sello que deja pasar petróleo no sirve"]},
{"t":"Sistemas petroleros","c":2,"e":"Una trampa ya está llena hasta su punto de derrame (el punto más bajo del cierre) y sigue llegando petróleo. ¿Qué ocurre con el petróleo adicional?","o":["Se acumula dentro de la roca sello","Aumenta la presión hasta romper la roca madre","Se derrama por el punto más bajo del cierre y sigue migrando hacia otra trampa","Se convierte en gas dentro de la trampa"]},
{"t":"Sistemas petroleros","c":3,"e":"Una roca madre con kerógeno tipo III, rica en restos de plantas terrestres, alcanzó la ventana de generación. ¿Qué hidrocarburo se espera principalmente?","o":["Petróleo liviano en abundancia","Crudo extrapesado","Ninguno, porque el tipo III no genera hidrocarburos","Gas"]},
{"t":"Sistemas petroleros","c":0,"e":"Una roca madre generó petróleo hace entre 80 y 60 millones de años. En la zona hay tres anticlinales formados hace 100, 70 y 40 millones de años. ¿Cuál tiene más probabilidad de estar lleno?","o":["El de 100 millones de años, porque ya existía cuando el petróleo migró","El de 40 millones de años, porque es el más reciente","El de 70 millones de años, porque se formó en medio de la generación","Los tres por igual, porque la edad de la trampa no importa"]},
{"t":"Sistemas petroleros","c":1,"e":"Una caliza tiene muy poca porosidad primaria pero está intensamente fracturada. ¿Puede funcionar como roca yacimiento?","o":["No, porque solo las areniscas pueden ser rocas yacimiento","Sí, porque las fracturas aportan permeabilidad y algo de espacio para almacenar fluidos","No, porque las fracturas siempre dejan escapar todo el petróleo","Sí, pero solo como roca madre"]},
{"t":"Sistemas petroleros","c":2,"e":"Al bajar la presión de un yacimiento de gas seco hasta las condiciones de superficie, ¿qué ocurre con el fluido?","o":["Deja caer líquido dentro de la roca, como un gas condensado","Libera burbujas de gas, como un petróleo negro","Se mantiene como gas tanto en el yacimiento como en superficie","Se solidifica en los poros"]},
{"t":"Sistemas petroleros","c":3,"e":"Un núcleo muestra arenas con buena porosidad y manchas de petróleo residual, pero la trampa hoy está llena de agua. ¿Qué explicación es más coherente?","o":["Que nunca llegó petróleo a esa trampa","Que el petróleo residual se formó dentro de la misma arena","Que el núcleo se contaminó con el lodo de perforación y la trampa siempre estuvo vacía","Que la trampa se llenó en el pasado y luego perdió el petróleo, por ejemplo por una falla en el sello"]},
{"t":"Sistemas petroleros","c":0,"e":"En una cuenca poco explorada aparecen menes (afloramientos naturales de petróleo). ¿Qué indican para la exploración?","o":["Que hay una roca madre que generó petróleo, aunque algunas trampas o sellos hayan dejado escapar parte de él","Que la cuenca no tiene ningún potencial, porque el petróleo ya se perdió","Que todas las trampas de la cuenca están llenas","Que no existe roca madre en la cuenca"]},
{"t":"Sistemas petroleros","c":1,"e":"Dos areniscas tienen la misma porosidad: una con granos gruesos y bien escogidos, y otra con granos finos mezclados con arcilla. ¿Cuál tendrá mayor permeabilidad?","o":["La de granos finos con arcilla, porque la arcilla conecta los poros","La de granos gruesos y bien escogidos, porque sus poros son más grandes y están mejor conectados","Ambas igual, porque tienen la misma porosidad","Ninguna, porque las areniscas no son permeables"]},
{"t":"Riesgo geológico y reservas","c":2,"e":"Un campo produce 100.000 b/d y su producción cae 10 % cada año respecto al año anterior. Sin pozos nuevos, ¿cuánto producirá aproximadamente dentro de dos años?","o":["Unos 90.000 b/d","Unos 80.000 b/d","Unos 81.000 b/d","Unos 72.900 b/d"]},
{"t":"Riesgo geológico y reservas","c":3,"e":"Un pozo exploratorio tiene 30 % de probabilidad de éxito. Si tiene éxito la ganancia neta es de 150 MM$, y si fracasa se pierden 50 MM$. ¿Cuál es el valor esperado de perforarlo?","o":["45 MM$","−5 MM$","100 MM$","10 MM$"]},
{"t":"Riesgo geológico y reservas","c":0,"e":"Si un éxito vale 200 MM$ netos y un pozo seco cuesta 50 MM$, ¿qué probabilidad de éxito mínima hace que el valor esperado sea cero?","o":["0,20","0,25","0,50","0,80"]},
{"t":"Riesgo geológico y reservas","c":1,"e":"Un yacimiento tiene 10 km² de área, 20 m de espesor neto, 20 % de porosidad y 25 % de saturación de agua. ¿Qué volumen de petróleo contiene en condiciones de yacimiento?","o":["Unos 3 millones de m³","Unos 30 millones de m³","Unos 40 millones de m³","Unos 200 millones de m³"]},
{"t":"Riesgo geológico y reservas","c":2,"e":"Un yacimiento de crudo extrapesado con POES de 500 MMbbl tiene un recobro en frío de 8 %. Con inyección de vapor podría llegar a 20 %. ¿Cuántas veces se multiplicarían sus reservas?","o":["12 veces","1,2 veces","2,5 veces","No cambian, porque el POES es el mismo"]},
{"t":"Riesgo geológico y reservas","c":3,"e":"Una empresa perfora dos prospectos independientes, cada uno con probabilidad de éxito de 0,2. ¿Cuál es la probabilidad de que ambos resulten secos?","o":["0,04","0,16","0,80","0,64"]},
{"t":"Riesgo geológico y reservas","c":0,"e":"La estimación probabilística de un campo da P90 = 40, P50 = 70 y P10 = 120 MMbbl. ¿Qué afirmación es correcta?","o":["Hay 90 % de probabilidad de recuperar al menos 40 MMbbl y solo 10 % de superar 120 MMbbl","Hay 90 % de probabilidad de recuperar al menos 120 MMbbl","Lo más probable es recuperar exactamente 40 MMbbl","El P10 es el escenario que aceptan los bancos como garantía"]},
{"t":"Riesgo geológico y reservas","c":1,"e":"Un descubrimiento de 20 MMbbl está en aguas profundas, a 300 km de cualquier infraestructura. ¿Por qué podría no registrarse como reserva?","o":["Porque solo se registran como reservas los volúmenes en tierra firme","Porque, aunque el petróleo exista, desarrollarlo puede costar más de lo que vale: todavía no es comercial","Porque un descubrimiento nunca se registra como reserva hasta agotarse","Porque 20 MMbbl está por debajo del mínimo legal de reservas"]},
{"t":"Riesgo geológico y reservas","c":2,"e":"Un geólogo asigna 0,5 a la roca madre y 0,5 al sello; los demás factores valen 1,0. Un estudio sísmico solo puede mejorar el sello a 0,9. ¿Cuál es el Pg antes y después del estudio?","o":["0,50 antes y 0,90 después","0,50 antes y 0,70 después","0,25 antes y 0,45 después","0,25 antes y 0,90 después"]},
{"t":"Riesgo geológico y reservas","c":3,"e":"Un campo con POES de 250 MMbbl ha producido 30 MMbbl. Una revisión baja su factor de recobro estimado de 40 % a 30 %. ¿Cuáles son sus nuevas reservas remanentes?","o":["75 MMbbl","70 MMbbl","25 MMbbl","45 MMbbl"]},
{"t":"Mecanismos de empuje y recobro","c":0,"e":"Un pozo atraviesa una arena con 10 m de capa de gas arriba, 15 m de petróleo en el medio y agua abajo. ¿Dónde conviene abrirlo (cañonearlo) a producción?","o":["Solo en la zona de petróleo, lejos de los contactos con el gas y con el agua","En toda la arena, para producir todos los fluidos a la vez","Solo en la capa de gas, para aprovechar su presión","Solo en la zona de agua, para que empuje el petróleo"]},
{"t":"Mecanismos de empuje y recobro","c":1,"e":"En un yacimiento sin capa de gas inicial, la relación gas-petróleo producida empieza a subir con fuerza tras meses de producción. ¿Qué indica?","o":["Que el acuífero está invadiendo el yacimiento","Que la presión cayó por debajo del punto de burbujeo y se está liberando gas en el yacimiento","Que se descubrió una nueva capa de gas por encima del yacimiento","Que el petróleo se está volviendo más pesado"]},
{"t":"Mecanismos de empuje y recobro","c":2,"e":"Un yacimiento con empuje por gas en solución pierde presión muy rápido. ¿Qué medida ayuda más a elevar su recobro?","o":["Producir a la máxima tasa posible antes de que la presión se agote","Cerrar el campo de forma definitiva","Inyectar agua o gas para mantener la presión (recuperación secundaria)","Perforar los pozos más cerca del tope del yacimiento"]},
{"t":"Mecanismos de empuje y recobro","c":3,"e":"Un pozo con empuje hidráulico produce 1.000 barriles diarios de líquido con 90 % de agua. ¿Cuánto petróleo produce?","o":["900 barriles diarios","1.000 barriles diarios","10 barriles diarios","100 barriles diarios"]},
{"t":"Mecanismos de empuje y recobro","c":0,"e":"Un pozo con empuje hidráulico se produce a una tasa muy alta y el agua llega mucho antes de lo previsto. ¿Qué fenómeno ocurrió?","o":["Conificación: la caída de presión cerca del pozo hizo subir el agua en forma de cono","Liberación de gas por debajo del punto de burbujeo","Compactación de la roca alrededor del pozo","Formación de una capa de gas secundaria"]},
{"t":"Mecanismos de empuje y recobro","c":1,"e":"Un yacimiento de 80 MMbbl tiene un recobro primario de 12 %, y la inyección de agua le agrega 18 puntos más. ¿Cuánto petróleo se recupera en total?","o":["14,4 MMbbl","24 MMbbl","9,6 MMbbl","30 MMbbl"]},
{"t":"Mecanismos de empuje y recobro","c":2,"e":"Dos yacimientos producen el mismo volumen. En A la presión casi no baja; en B la presión cae rápido y la relación gas-petróleo sube. ¿Qué mecanismos sugieren?","o":["A, gas en solución, y B, empuje hidráulico","Ambos, capa de gas","A, empuje hidráulico, y B, gas en solución","A, compactación, y B, drenaje por gravedad"]},
{"t":"Mecanismos de empuje y recobro","c":3,"e":"¿Qué condiciones favorecen el drenaje por gravedad?","o":["Capas delgadas y horizontales producidas a la máxima tasa","Rocas de muy baja permeabilidad vertical","Un gran acuífero activo debajo del petróleo","Yacimientos de gran espesor o muy inclinados, con buena permeabilidad vertical y producción lenta"]},
{"t":"Mecanismos de empuje y recobro","c":0,"e":"En un yacimiento con capa de gas, se observa que el contacto gas-petróleo baja y se acerca a los pozos. ¿Qué acción es la más apropiada?","o":["Reducir la tasa de producción o cerrar los pozos más altos para no producir gas libre","Aumentar la tasa para producir el petróleo antes de que llegue el gas","Abrir los pozos en la capa de gas para venderla","No hacer nada, porque el gas no afecta el recobro"]},
{"t":"Mecanismos de empuje y recobro","c":1,"e":"Un yacimiento de 50 MMbbl con gas en solución recupera 15 %. Con inyección de agua llegaría a 35 %, a un costo de 300 MM$. Si cada barril adicional deja 20 US$ netos, ¿conviene el proyecto?","o":["Sí: recupera 17,5 MMbbl que dejan 350 MM$","No: recupera 10 MMbbl adicionales que dejan 200 MM$, menos que los 300 MM$ de inversión","Sí: el recobro sube más del doble","No se puede saber sin conocer el POES"]}
]$j$::jsonb) x
 where not exists (select 1 from parcial.preguntas p where p.enunciado = x->>'e');

